   "titulo": "Bukele inscribió su candidatura para un tercer mandato en El Salvador",
   "resumen": "Elecciones El Salvador 2027 | El presidente de El Salvador, Nayib Bukele, inscribió la noche del jueves su candidatura para un tercer mandato, apoyado en el amplio respaldo popular a su guerra contra las pandillas, observaron periodistas de la AFP.",
   "fuente": "El Comercio",
   "url": "https://elcomercio.pe/mundo/centroamerica/nayib-bukele-inscribio-su-candidatura-para-un-tercer-mandato-en-el-salvador-elecciones-2027-tribunal-supremo-electoral-ultimas-noticia/",
   "fecha": "2026-11-20T03:53:22Z",
   "tipo": "comercial",
   "genero": "noticia",
   "imagen": "https://elcomercio.pe/resizer/v2/54WDEVLGURBBHHVTVO5O7IIXPE.jpg?auth=e8a9a9a721e00dca7918a187860daa3e1c6855f2b0120f57076876da8f0889fd&smart=true&width=1200&height=800",
