   "resumen": "El papa León XIV, actual máximo representante de la Iglesia católica pertenece a la Orden de San Agustín (O.S.A.), una congregación religiosa cuya espiritualidad está profundamente arraigada en el pensamiento, la teología y los escritos del célebre obispo de Hipona.",
   "fuente": "RPP",
   "url": "https://rpp.pe/columnistas/ricardoleninalfredofallacarrillo/san-agustin-el-gran-pensador-que-inspira-al-papa-leon-xiv-noticia-1718698",
