   "ambito": "pendiente",
   "procedencia": "directa",
   "sintesis": "El papa León XIV, actual máximo representante de la Iglesia católica pertenece a la Orden de San Agustín (O.S.A.), una congregación religiosa cuya espiritualidad está profundamente arraigada en el pensamiento, la teología y los escritos del célebre obispo de Hipona. Esta pertenencia no es puramente nominal, sino que impregna la visión pastoral e intelectual del pontífice, quien encuentra en la tradición agustiniana una fuente viva para dialogar con los profundos anhelos y dilemas del hombre contemporáneo.",
   "puntos": [
    "El papa León XIV, actual máximo representante de la Iglesia católica pertenece a la Orden de San Agustín (O.S.A.), una congregación religiosa cuya espiritualidad está profundamente arraigada en el pensamiento, la teología y los escritos del célebre obispo de Hipona.",
    "Esta pertenencia no es puramente nominal, sino que impregna la visión pastoral e intelectual del pontífice, quien encuentra en la tradición agustiniana una fuente viva para dialogar con los profundos anhelos y dilemas del hombre contemporáneo.",
    "Nacido en Tagaste (en el actual territorio de Argelia) en el año 354, Aurelio Agustín vivió una juventud apasionada y marcada por la búsqueda constante de la verdad a través de diversas corrientes filosóficas y religiosas, como el maniqueísmo y el escepticismo."
   ],
